    for cand in candidates:
        try:
            net = canon(tools.repair(cand))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            continue

    if not repaired:
        try:
            net = canon(tools.repair([]))
            if tools.is_valid(net):
                repaired.add(net)
        except Exception:
            pass
    if not repaired:
        return []

    # Start with low-energy repairs while ensuring structural variety.
    ordered = sorted(repaired, key=lambda x: tools.energy(x))
    seeds = []
    for net in ordered:
        if all(dist(net, old) >= 6 for old in seeds):
            seeds.append(net)
        if len(seeds) >= 18:
            break
    for net in ordered:
        if len(seeds) >= 30:
            break
        if net not in seeds:
            seeds.append(net)

    for net in seeds:
        if tools.lp_calls_left <= 0:
            break
        try:
            evaluate(net)
        except Exception as exc:
            if type(exc).__name__ == "BudgetExhausted":
                break
            raise

