    # repairs are considered first; all remaining budget goes to search.
    repairs = set()
    for cand in candidates:
        try:
            net = canon(tools.repair(cand))
            if tools.is_valid(net):
                repairs.add(net)
        except Exception:
            continue
    if not repairs:
        try:
            repairs.add(canon(tools.repair([])))
        except Exception:
